sysauto_script.script:
(function runNtBgExpiryReminderJob() {
    var T_CUST   = 'x_birl3_clm_clm_customer_master1';
    var T_MATRIX = 'x_birl3_clm_approval_matrix';
    var EVENT_NAME = 'x_birl3_clm.nt_bg_expiry_reminder';

    // Helper: Get YYYY-MM-DD date string offset by N days from today
    function getOffsetDateStr(days) {
        var gd = new GlideDate();
        if (days !== 0) {
            gd.addDaysLocalTime(days);
        }
        return gd.getValue(); // YYYY-MM-DD
    }

    // 1. Define the 4 Target Milestone Dates (T-30, T-15, T-7, Expired Day T-0)
    var milestones = [
        { code: 'T30', daysLeft: 30, label: '30 Days to Expiry', dateStr: getOffsetDateStr(30) },
        { code: 'T15', daysLeft: 15, label: '15 Days to Expiry', dateStr: getOffsetDateStr(15) },
        { code: 'T7',  daysLeft: 7,  label: '7 Days to Expiry',  dateStr: getOffsetDateStr(7)  },
        { code: 'EXP', daysLeft: 0,  label: 'Expired Today',     dateStr: getOffsetDateStr(0)  }
    ];

    var dateToMilestone = {};
    var targetDates = [];
    for (var i = 0; i < milestones.length; i++) {
        dateToMilestone[milestones[i].dateStr] = milestones[i];
        targetDates.push(milestones[i].dateStr);
    }

    // 2. Cache ZCH Recipients by Zone (plus PAN-India ZCH / HO Commercial)
    var zoneZchMap = {};
    var panIndiaUsers = [];

    var mGr = new GlideRecord(T_MATRIX);
    var rqc = mGr.addQuery('role_name', 'CONTAINS', 'ZCH');
    rqc.addOrCondition('role_name', 'CONTAINS', 'Zonal');
    var ctqc = mGr.addQuery('customer_type', 'CONTAINS', 'Non-Trade');
    ctqc.addOrCondition('customer_type', 'CONTAINS', 'non_trade');
    ctqc.addOrCondition('customer_type', 'CONTAINS', 'non-trade');
    mGr.query();

    while (mGr.next()) {
        var uId = (mGr.getValue('approver_user') || '').trim();
        if (!uId) continue;

        var pIndia = mGr.getValue('pan_india');
        if (pIndia === '1' || pIndia === 'true' || pIndia === true) {
            if (panIndiaUsers.indexOf(uId) === -1) panIndiaUsers.push(uId);
        }

        var z = (mGr.getValue('zone') || '').trim();
        if (z) {
            if (!zoneZchMap[z]) zoneZchMap[z] = [];
            if (zoneZchMap[z].indexOf(uId) === -1) zoneZchMap[z].push(uId);
        }
    }

    function getRecipientsForZone(zoneCode) {
        var list = [];
        var zList = (zoneCode && zoneZchMap[zoneCode]) ? zoneZchMap[zoneCode] : [];
        for (var a = 0; a < zList.length; a++) {
            if (list.indexOf(zList[a]) === -1) list.push(zList[a]);
        }
        // Fallback to PAN-India ZCH if zone has no specific mapping
        if (list.length === 0) {
            for (var b = 0; b < panIndiaUsers.length; b++) {
                if (list.indexOf(panIndiaUsers[b]) === -1) list.push(panIndiaUsers[b]);
            }
        }
        return list;
    }

    // 3. Query Non-Trade Sites Matching Any of the 4 Milestone Dates
    var custGr = new GlideRecord(T_CUST);
    custGr.addQuery('cg1', 'N01'); // Non-Trade
    custGr.addQuery('bank_guarantee', '>', 0);
    custGr.addQuery('bg_expiry_date', 'IN', targetDates.join(','));
    custGr.orderBy('pan');
    custGr.orderBy('customer_code_sap');
    custGr.query();

    // Group matching sites by (PAN + Zone + MilestoneCode) to send consolidated emails
    var batches = {};

    while (custGr.next()) {
        var rawExp = (custGr.getValue('bg_expiry_date') || '').split(' ')[0];
        var ms = dateToMilestone[rawExp];
        if (!ms) continue;

        var pan = (custGr.getValue('pan') || '').trim();
        var zone = (custGr.getValue('zone') || '').trim();
        var siteCode = (custGr.getValue('customer_code_sap') || '').trim();
        var groupKey = (pan || siteCode) + '|' + zone + '|' + ms.code;

        if (!batches[groupKey]) {
            batches[groupKey] = {
                anchorSysId: custGr.getUniqueValue(),
                pan: pan,
                zone: zone,
                milestone: ms,
                siteSysIds: []
            };
        }
        batches[groupKey].siteSysIds.push(custGr.getUniqueValue());
    }

    // 4. Fire One Event per Consolidated Batch
    var firedCount = 0;
    for (var key in batches) {
        if (!batches.hasOwnProperty(key)) continue;
        var b = batches[key];

        var recipients = getRecipientsForZone(b.zone);
        if (recipients.length === 0) {
            gs.warn('CLM BG Expiry Reminder: No ZCH recipient found for Zone ' + b.zone + ' (PAN: ' + b.pan + ')');
            continue;
        }

        var anchorGr = new GlideRecord(T_CUST);
        if (anchorGr.get(b.anchorSysId)) {
            var payload = {
                code: b.milestone.code,
                daysLeft: b.milestone.daysLeft,
                expiryDate: b.milestone.dateStr,
                pan: b.pan,
                zone: b.zone,
                siteSysIds: b.siteSysIds
            };

            gs.eventQueue(
                EVENT_NAME,
                anchorGr,
                recipients.join(','),
                JSON.stringify(payload)
            );
            firedCount++;
        }
    }

    gs.info('CLM NT BG Expiry Daily Reminder Job completed. Batches queued: ' + firedCount);
})();
